// librarySourceDelete: DELETE /libraries/{id}/sources/{plugin_id} — the
// clear-to-inherit action: the library-scope row is removed and the library
// falls back to the module-scope resolution (or the config default) on the
// next read. Idempotent like the store call beneath it: deleting an absent
// row still answers 204. The clear may RESTORE the source (the inherited
// resolution can be enabled), so the scoped library wakes through
// Deps.OnSourceGateChanged — the dormant-source contract's "clearing the
// gate restores derivation through the queue without any rescan".
//
// @Summary     Clear a library's metadata-source gate
// @Tags        admin
// @ID          delete-library-source-gate
// @Router      /libraries/{id}/sources/{plugin_id} [delete]
// @Param       id        path int    true "library id"
// @Param       plugin_id path string true "plugin id"
// @Success     204 "gate cleared (absent row: still 204, idempotent)"
// @Failure     400 {object} errorBody
// @Failure     404 {object} errorBody
// @Failure     500 {object} errorBody
// @Failure     503 {object} errorBody
func (a *app) librarySourceDelete(w http.ResponseWriter, r *http.Request) {
	lib, pluginID, ok := a.libraryGateTarget(w, r)
	if !ok {
		return
	}
	if err := a.deps.Store.DeleteMetadataSourcePref(r.Context(), lib.ModuleID, lib.ID, pluginID); err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	if a.deps.OnSourceGateChanged != nil {
		a.deps.OnSourceGateChanged(r.Context(), lib.ID)
	}
	w.WriteHeader(http.StatusNoContent)
}

// sourcePreviewRequest is the body of POST /admin/sources/preview:
// library_id names the one library whose rows are composed (pointer presence:
// a MISSING library_id is a non-canonical body, 400 — the sourcePatchRequest
// convention), gates is the HYPOTHETICAL gate vector keyed by plugin id — a
// key present pins that title source's walk binding to the requested
// enablement for the after pass only; keys absent keep the live resolution.
// An empty/absent gates map composes the after pass under the live gates.
type sourcePreviewRequest struct {
	LibraryID *int64          `json:"library_id"`
	Gates     map[string]bool `json:"gates"`
}

// sourcePreviewRow is one composed row of one preview pass: the row id (the
// ser_/itm_ id space — both row kinds of the library compose here), the name
// the production composer produced under that pass's gates, and the no_data
// marker (true when the composition had no title-source data to compose
// from — see itemNoData/seriesNoData).
type sourcePreviewRow struct {
	ItemID string `json:"item_id"`
	Name   string `json:"name"`
	NoData bool   `json:"no_data"`
}

// sourcePreviewResponse is the wire shape of POST /admin/sources/preview: the
// SAME rows composed under the live gates (before) and the request's
// hypothetical vector (after) — symmetric by construction (one row slice,
// composed twice), never two walks over two reads.
type sourcePreviewResponse struct {
	Before []sourcePreviewRow `json:"before"`
	After  []sourcePreviewRow `json:"after"`
}

// adminSourcePreview: POST /admin/sources/preview — the composition preview
// (plugin-title-enrichment D7): the production composer (namerFor's
// seriesName/itemName walks — the SAME namer the served display_names use)
// run TWICE over the same rows, once under the live gates (the before pass —
// its names are byte-identical to what /series and /items serve) and once
// under the request's hypothetical gate vector (the after pass). WRITES
// NOTHING: every call here is a read — the gate vector lives only in the
// copied namer's bindings, no prefs row is touched, no wake fires, no
// document changes. Validation is first (the adminSourcePatch order):
// malformed body / missing library_id / unknown gate plugin → 400, unknown
// library → 404, all before any read; a nil SourceInventory → 503 (the
// adminSources posture — the closure is the gate-vector vocabulary). The
// rows are the library's series then its items (the served listing shapes),
// keyed by row id; the no_data marker is computed PER PASS (the envelope's
// "symmetric before/after name sets with the no_data marker").
//
// @Summary     Preview composition under a hypothetical gate vector
// @Tags        admin
// @ID          admin-source-preview
// @Router      /admin/sources/preview [post]
// @Param       request body sourcePreviewRequest true "library and hypothetical gates"
// @Success     200 {object} sourcePreviewResponse
// @Failure     400 {object} errorBody
// @Failure     404 {object} errorBody
// @Failure     500 {object} errorBody
// @Failure     503 {object} errorBody
func (a *app) adminSourcePreview(w http.ResponseWriter, r *http.Request) {
	if a.deps.SourceInventory == nil {
		writeError(w, http.StatusServiceUnavailable, "unavailable", "sources endpoint disabled", false)
		return
	}
	var req sourcePreviewRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", "malformed JSON body", false)
		return
	}
	if req.LibraryID == nil {
		writeError(w, http.StatusBadRequest, "bad_request", "library_id is required", false)
		return
	}
	lib, err := a.deps.Store.GetLibrary(r.Context(), *req.LibraryID)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			writeError(w, http.StatusNotFound, "not_found",
				"library "+strconv.FormatInt(*req.LibraryID, 10)+" not found", false)
			return
		}
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	ids, _, _ := a.deps.SourceInventory(r.Context())
	for pluginID := range req.Gates {
		if !containsString(ids, pluginID) {
			writeError(w, http.StatusBadRequest, "bad_request", "unknown plugin "+strconv.Quote(pluginID), false)
			return
		}
	}
	// The production composer, twice: the live namer is EXACTLY the one
	// namerFor builds for serving (so before == served display_names), and
	// the after namer is a copy whose title-walk bindings carry the
	// hypothetical vector — every other composition input is shared.
	live, err := a.namerFor(r.Context(), lib.ID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	hypo := live
	hypo.titleSources = gateOverriddenSources(live.titleSources, req.Gates)
	srs, err := a.deps.Store.QuerySeries(r.Context(), lib.ID, "")
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	out := sourcePreviewResponse{Before: []sourcePreviewRow{}, After: []sourcePreviewRow{}}
	for _, sr := range srs {
		override, err := a.storedTitle(r.Context(), sr.ID)
		if err != nil {
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
			return
		}
		doc := docMap(sr.Document)
		out.Before = append(out.Before, sourcePreviewRow{
			ItemID: sr.ID,
			Name:   live.seriesName(sr, override),
			NoData: seriesNoData(live, doc, override),
		})
		out.After = append(out.After, sourcePreviewRow{
			ItemID: sr.ID,
			Name:   hypo.seriesName(sr, override),
			NoData: seriesNoData(hypo, doc, override),
		})
	}
	offset := 0
	for {
		page, err := a.deps.Store.QueryItems(r.Context(), lib.ID, "", titleCountPageSize, offset)
		if err != nil {
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
			return
		}
		if len(page) == 0 {
			break
		}
		offset += len(page)
		for _, it := range page {
			override, err := a.storedTitle(r.Context(), it.ID)
			if err != nil {
				writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
				return
			}
			// The per-row series-override point read (the itemDTOs seam)
			// applies to each pass's own namer copy — the joined series'
			// stored override is shared, but the {title} inside the composed
			// name walks the pass's OWN bindings.
			liveRow, err := a.withSeriesOverride(r.Context(), live, it.Document)
			if err != nil {
				writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
				return
			}
			hypoRow, err := a.withSeriesOverride(r.Context(), hypo, it.Document)
			if err != nil {
				writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
				return
			}
			doc := docMap(it.Document)
			out.Before = append(out.Before, sourcePreviewRow{
				ItemID: it.ID,
				Name:   liveRow.itemName(it, override),
				NoData: itemNoData(liveRow, doc, override),
			})
			out.After = append(out.After, sourcePreviewRow{
				ItemID: it.ID,
				Name:   hypoRow.itemName(it, override),
				NoData: itemNoData(hypoRow, doc, override),
			})
		}
	}
	writeJSON(w, http.StatusOK, out)
}

// gateOverriddenSources applies the hypothetical gate vector over a COPY of
// the live title-walk bindings (plugin-title-enrichment D7): a vector key
// pins that binding's Enabled to the requested value, an absent key keeps the
// live resolution. The live slice is never mutated — the before pass keeps
// reading it — so the before/after passes stay independent views of one read.
func gateOverriddenSources(live []titleSourceBinding, gates map[string]bool) []titleSourceBinding {
	if len(gates) == 0 {
		return live
	}
	out := make([]titleSourceBinding, len(live))
	copy(out, live)
	for i := range out {
		if enabled, ok := gates[out[i].ID]; ok {
			out[i].Enabled = enabled
		}
	}
	return out
}

// seriesNoData is a series row's no_data verdict for one pass: the row's name
// resolved PAST the config-driven title walk — the walk (over the pass's
// gate-resolved bindings) produced nothing while actually being part of the
// chain. An operator override short-circuits before any namespace is
// consulted (never no_data: the name carries no source data by design); the
// "raw" group style skips the walk deliberately (never no_data); a walk hit
// (before pass on a titled row) is false — the marker is the want-of-title-
// data floor, not a change detector.
func seriesNoData(n namer, doc map[string]any, override string) bool {
	if override != "" || n.groupStyle == "raw" {
		return false
	}
	return n.sourceTitle(doc) == ""
}

// itemNoData is an item row's no_data verdict for one pass: the name resolved
// past BOTH legs above the walk — the operator override and the composed
// element name — and the walk over the item's OWN namespaces (plugin-title-
// enrichment: the item walk leg) produced nothing. A won composed name is
// never no_data even when its {title} floored: the title data question for
// THAT series is the series row's own marker in the same preview; here the
// composition chain supplied a name above the item's own walk.
func itemNoData(n namer, doc map[string]any, override string) bool {
	if override != "" {
		return false
	}
	if n.elementTmpl != "" {
		if _, ok := n.elementName(doc); ok {
			return false
		}
	}
	return n.sourceTitle(doc) == ""
}

// affectedSourceModules returns the module ids whose metadata-source chain
// binds pluginID at module scope — the modules one module-wide gate write
// covers and (on enable) the libraries one notify sweep wakes. Only the
// metadata-source chain counts: a plugin bound to no module as a metadata
// source has no gate to write (the write set is empty, the response queued=0).
func (a *app) affectedSourceModules(ctx context.Context, pluginID string) ([]string, error) {
	moduleIDs, err := a.deps.ModuleIDs(ctx)
	if err != nil {
		return nil, err
	}
	var affected []string
	for _, moduleID := range moduleIDs {
		pids, _, _, err := a.deps.ModuleSources(ctx, moduleID, 0)
		if err != nil {
			return nil, err
		}
		if containsString(pids, pluginID) {
			affected = append(affected, moduleID)
		}
	}
	return affected, nil
}

// containsString reports whether the slice carries the value — the membership
// check the patch handler uses for both the boot-set validation and the
// affected-module/library filters.
func containsString(xs []string, v string) bool {
	for _, x := range xs {
		if x == v {
			return true
		}
	}
	return false
}

// collectSourceAggregate gathers everything one GET /admin/sources response
// renders: the boot-literal inventory, the Deps.Status health snapshot, the
// registry module list, the module-scope gate resolution per module, the
// per-library resolution per library row, and (when asked) the on-demand
// title counts. Read-only: nothing here writes. Error → the caller 500s
// (fail-fast, like every other read).
func (a *app) collectSourceAggregate(ctx context.Context, wantCounts bool) (sourceAdminAggregate, error) {
	ids, names, descriptions := a.deps.SourceInventory(ctx)
	healths, err := a.sourceHealths(ctx)
	if err != nil {
		return sourceAdminAggregate{}, err
	}
	moduleIDs, err := a.deps.ModuleIDs(ctx)
	if err != nil {
		return sourceAdminAggregate{}, err
	}
	moduleScope := make(map[string]sourceResolution, len(moduleIDs))
	for _, moduleID := range moduleIDs {
		res, err := a.moduleSources(ctx, moduleID, 0)
		if err != nil {
			return sourceAdminAggregate{}, err
		}
		moduleScope[moduleID] = res
	}
	libs, err := a.deps.Store.ListLibraries(ctx)
	if err != nil {
		return sourceAdminAggregate{}, err
	}
	libScope := make(map[int64]map[string]bool, len(libs))
	for _, lib := range libs {
		res, err := a.moduleSources(ctx, lib.ModuleID, lib.ID)
		if err != nil {
			return sourceAdminAggregate{}, err
		}
		libScope[lib.ID] = res.enabledByID()
	}
	var counts map[string]sourceTitleCounts
	if wantCounts {
		if counts, err = a.sourceTitleCounts(ctx, ids); err != nil {
			return sourceAdminAggregate{}, err
		}
	}
	return sourceAdminAggregate{
		inventoryIDs: ids,
		names:        names,
		descriptions: descriptions,
		healths:      healths,
		moduleIDs:    moduleIDs,
		moduleScope:  moduleScope,
		libs:         libs,
		libScope:     libScope,
		counts:       counts,
	}, nil
}

// moduleSources wraps one Deps.ModuleSources call into a sourceResolution —
// the one translation between the closure's parallel slices and the rest of
// the handler.
func (a *app) moduleSources(ctx context.Context, moduleID string, libraryID int64) (sourceResolution, error) {
	pids, prs, ens, err := a.deps.ModuleSources(ctx, moduleID, libraryID)
	if err != nil {
		return sourceResolution{}, err
	}
	return sourceResolution{pluginIDs: pids, priorities: prs, enabled: ens}, nil
}

// sourceHealths indexes the Deps.Status snapshot by plugin id (the health
// block lookup per inventory entry). A nil closure means no health blocks at
// all; a closure error is a real failure and propagates (the caller 500s,
// exactly like the /admin/status handler).
func (a *app) sourceHealths(ctx context.Context) (map[string]PluginHealth, error) {
	if a.deps.Status == nil {
		return map[string]PluginHealth{}, nil
	}
	st, err := a.deps.Status(ctx)
	if err != nil {
		return nil, err
	}
	out := make(map[string]PluginHealth, len(st.Plugins))
	for _, h := range st.Plugins {
		out[h.ID] = h
	}
	return out, nil
}

// renderSources builds the response rows in inventory (boot) order: every
// loaded plugin renders, even one with no module binding, no health report,
// and no capabilities — the aggregate is the loaded set, not the healthy set.
// Maps initialize non-nil so an empty block renders {} and never null.
func (a *app) renderSources(ctx context.Context, agg sourceAdminAggregate) []sourceAdminSource {
	out := make([]sourceAdminSource, 0, len(agg.inventoryIDs))
	for _, id := range agg.inventoryIDs {
		src := sourceAdminSource{
			PluginID:     id,
			Name:         agg.names[id],
			Description:  agg.descriptions[id],
			Capabilities: []string{},
			Chains:       []sourceAdminChain{},
			Effective: sourceAdminEffective{
				Modules:   map[string]bool{},
				Libraries: map[string]bool{},
			},
		}
		if a.deps.PluginCapabilities != nil {
			if caps, known := a.deps.PluginCapabilities(ctx, id); known && len(caps) > 0 {
				src.Capabilities = caps
			}
		}
		if h, ok := agg.healths[id]; ok {
			health := h
			src.Health = &health
		}
		for _, moduleID := range agg.moduleIDs {
			res := agg.moduleScope[moduleID]
			for i, pid := range res.pluginIDs {
				if pid != id {
					continue
				}
				src.Chains = append(src.Chains, sourceAdminChain{ModuleID: moduleID, Position: res.priorities[i]})
				src.Effective.Modules[moduleID] = res.enabled[i]
			}
		}
		for _, lib := range agg.libs {
			if enabled, ok := agg.libScope[lib.ID][id]; ok {
				src.Effective.Libraries[strconv.FormatInt(lib.ID, 10)] = enabled
			}
		}
		if agg.counts != nil {
			counts := agg.counts[id]
			src.TitleCounts = &counts
		}
		out = append(out, src)
	}
	return out
}

// titleCountPageSize pages the on-demand title-count items read (an
// O(all-rows) pass over every library's documents; QueryItems requires a
// positive limit, so the pass walks fixed-size pages).
const titleCountPageSize = 500

// sourceTitleCounts tallies, per loaded plugin, how many stored item and
// series rows carry the plugin's namespace WITH title data. Read per request
// from the documents — never stored, never on hot paths (the spec's
// "computed on demand"). A namespace counts when its `title` is a non-empty
// string or an object with at least one non-empty string value — any
// language, matching what the composition could pick from.
func (a *app) sourceTitleCounts(ctx context.Context, pluginIDs []string) (map[string]sourceTitleCounts, error) {
	loaded := make(map[string]bool, len(pluginIDs))
	for _, id := range pluginIDs {
		loaded[id] = true
	}
	libs, err := a.deps.Store.ListLibraries(ctx)
	if err != nil {
		return nil, err
	}
	counts := make(map[string]sourceTitleCounts)
	for _, lib := range libs {
		srs, err := a.deps.Store.QuerySeries(ctx, lib.ID, "")
		if err != nil {
			return nil, err
		}
		for _, sr := range srs {
			for _, id := range titledNamespaces(docMap(sr.Document), loaded) {
				c := counts[id]
				c.Series++
				counts[id] = c
			}
		}
		offset := 0
		for {
			page, err := a.deps.Store.QueryItems(ctx, lib.ID, "", titleCountPageSize, offset)
			if err != nil {
				return nil, err
			}
			if len(page) == 0 {
				break
			}
			offset += len(page)
			for _, it := range page {
				for _, id := range titledNamespaces(docMap(it.Document), loaded) {
					c := counts[id]
					c.Items++
					counts[id] = c
				}
			}
		}
	}
	return counts, nil
}

// titledNamespaces returns the loaded-plugin namespaces of one document's
// sources map that carry title data (hasTitleData) — the per-row unit of the
// title counts. Namespaces of unloaded plugins never count.
func titledNamespaces(doc map[string]any, loaded map[string]bool) []string {
	sources, _ := doc["sources"].(map[string]any)
	var out []string
	for id, ns := range sources {
		nsm, ok := ns.(map[string]any)
		if !loaded[id] || !ok || !hasTitleData(nsm) {
			continue
		}
		out = append(out, id)
	}
	return out
}

// hasTitleData reports whether one source namespace carries a usable title:
// a non-empty string, or an object with at least one non-empty string value
// (any language key — the count is language-agnostic; the composition picks).
func hasTitleData(ns map[string]any) bool {
	switch title := ns["title"].(type) {
	case string:
		return title != ""
	case map[string]any:
		for _, v := range title {
			if s, ok := v.(string); ok && s != "" {
				return true
			}
		}
	}
	return false
}
